function botanicalInfo(p){const known=botanical[p.name];const vegetable=p.category==='Potager'||p.zone==='Potager';const aromatic=p.category==='Aromatiques';return known||[p.name,p.exposure||'À vérifier selon la variété',p.watering||'Adapter au sol et à la météo',vegetable?'Printemps après les risques de gel pour les espèces sensibles':'Automne ou printemps selon espèce et climat','Vérifier la période et la méthode propres à cette espèce',aromatic?'Récolte selon la saison':vegetable?'Récolte selon le calendrier de culture':'Floraison ou récolte selon variété'];}
