async function wikiThumbnail(title,lang){const api='https://'+lang+'.wikipedia.org/w/api.php?action=query&titles='+encodeURIComponent(title)+'&prop=pageimages&pithumbsize=600&format=json&origin=*';const r=await fetch(api);if(!r.ok)return null;const data=await r.json();return Object.values(data.query?.pages||{}).find(p=>p.thumbnail?.source)?.thumbnail.source||null}
async function commonsThumbnail(term){const api='https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch='+encodeURIComponent('filetype:bitmap '+term)+'&gsrnamespace=6&gsrlimit=5&prop=imageinfo&iiprop=url&iiurlwidth=600&format=json&origin=*';const r=await fetch(api);if(!r.ok)return null;const data=await r.json();const pages=Object.values(data.query?.pages||{});return pages.find(p=>p.imageinfo?.[0]?.thumburl)?.imageinfo[0].thumburl||null}
async function findPhoto(name){const scientific=photoOverrides[name]||name;for(const [title,lang] of [[scientific,'en'],[name,'fr']]){try{const u=await wikiThumbnail(title,lang);if(u)return u}catch(e){}}try{return await commonsThumbnail(scientific)}catch(e){return null}}
async function loadBotanicalPhotos(){const nodes=[...document.querySelectorAll('[data-photo]')];await Promise.all(nodes.map(async el=>{const name=el.dataset.photo;if(!name)return;let promise=photoCache.get(name);if(!promise){promise=findPhoto(name);photoCache.set(name,promise)}const url=await promise;if(url&&el.isConnected){const img=document.createElement('img');img.src=url;img.alt='Photo botanique indicative : '+name;img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>{img.remove();photoCache.delete(name)};el.prepend(img)}}))}
function catalogView(){return '<h2>Catalogue de 50 plantes</h2><p class="muted">Photos et fiches botaniques. Les conseils sont indicatifs et varient selon les variétés.</p><div class="card"><label for="catalog-search">Rechercher</label><input id="catalog-search" placeholder="Nom ou catégorie"></div><div class="grid" id="catalog-results">'+catalog.map((p,i)=>'<article class="card"><div class="plant-emoji botanical-photo" data-photo="'+esc(p.name)+'">'+p.emoji+'</div><h3>'+esc(p.name)+'</h3><p class="muted">'+esc(p.category)+' · '+esc(p.exposure)+'</p><div class="actions"><button data-action="catalog-detail" data-id="'+i+'">Fiche complète</button><button class="primary" data-action="catalog-add" data-id="'+i+'">Ajouter</button></div></article>').join('')+'</div><p class="muted">Photographies : Wikipédia, lorsque disponibles. Consultez la page source pour les crédits et licences.</p>'}

