function careFor(p){const name=String(p.scientificName||p.name||'').toLocaleLowerCase('fr'),common=String(p.name||'').toLocaleLowerCase('fr');const care=careLibrary.find(c=>c.keys.some(k=>name===k||common===k));return care||null}
function carePanel(p){const c=careFor(p);if(!c)return '<section class="card care-unverified"><h3>🌿 Entretien à confirmer</h3><p>JARDÉO ne dispose pas encore de fiche détaillée fiable pour cette espèce. Vérifiez son nom botanique et sa variété auprès d’une source horticole avant de définir arrosage, taille ou rusticité.</p><p class="muted">Identification proposée : '+esc(p.scientificName||p.name)+'</p></section>';const items=[['☀️ Exposition',c.sun],['💧 Arrosage',c.water],['🌱 Sol',c.soil],['✂️ Taille',c.pruning],['🪴 Fertilisation',c.feeding],['❄️ Gel et rusticité',c.frost],['🐛 Maladies et parasites',c.issues],['📅 Conseil de saison',c.season]];return '<section class="card"><h3>🌿 Fiche d’entretien détaillée</h3><div class="care-grid">'+items.map(([k,v])=>'<div class="care-tile"><strong>'+esc(k)+'</strong><p>'+esc(v)+'</p></div>').join('')+'</div><p class="muted">Conseils généraux pour cette espèce. Adapter selon variété, âge, sol et météo à Villiers-sur-Loir.</p></section>'}

function botanicalDetail(p,back){const b=botanicalInfo(p);return '<button data-action="'+back+'">← Retour</button><article class="card"><div class="plant-emoji botanical-photo large" data-photo="'+esc(p.name)+'">'+esc(p.emoji||'🌱')+'</div><h2>'+esc(p.name)+'</h2><p class="muted"><a href="https://fr.wikipedia.org/wiki/Special:Search?search='+encodeURIComponent(b[0])+'" target="_blank" rel="noopener noreferrer">Voir les photographies et leurs crédits sur Wikipédia ↗</a></p><div class="botanical-info">'+[['Nom botanique',b[0]],['Exposition',b[1]],['Arrosage',b[2]],['Plantation',b[3]],['Taille et entretien',b[4]],['Floraison / récolte',b[5]]].map(([k,v])=>'<section><strong>'+esc(k)+'</strong><p>'+esc(v)+'</p></section>').join('')+'</div><p class="muted">Conseils généraux : adaptez-les à votre variété, à votre sol et à la météo.</p></article>'+carePanel(p)}

function plantCalendarTasks(){const key=year+'-'+String(month+1).padStart(2,'0');return state.plants.flatMap(p=>{const n=p.name.toLocaleLowerCase('fr');let actions=[];if([2,3,4].includes(month))actions.push('Vérifier les besoins de plantation et de reprise');if([5,6,7].includes(month))actions.push('Contrôler l’arrosage et le paillage');if([9,10].includes(month))actions.push('Préparer la protection hivernale si nécessaire');if((n.includes('tomate')||n.includes('courgette')||n.includes('fraisier'))&&[5,6,7,8].includes(month))actions.push('Surveiller la croissance et la récolte');if((n.includes('rosier')||n.includes('figuier')||n.includes('pommier'))&&[1,2].includes(month))actions.push('Vérifier la période de taille adaptée à la variété');return actions.map((a,i)=>({id:'plant-'+key+'-'+p.id+'-'+i,name:p.name+' : '+a,zone:p.zone,month:key}))})}
function seasonalTasks(){return seasonal[month].map((name,i)=>({id:`season-${year}-${month}-${i}`,name,zone:'Conseil saisonnier',month:`${year}-${String(month+1).padStart(2,'0')}`}))}
function taskList(){return [...seasonalTasks(),...plantCalendarTasks(),...state.tasks.filter(t=>t.month===`${year}-${String(month+1).padStart(2,'0')}`)]}
function home(){const today=localDateISO(),due=(state.reminders||[]).filter(r=>r.date<=today).sort((a,b)=>a.date.localeCompare(b.date)),upcoming=(state.reminders||[]).filter(r=>r.date>today).sort((a,b)=>a.date.localeCompare(b.date)),tasks=taskList().filter(t=>!state.done.includes(t.id)),weather=weatherData?.current,forecast=weatherData?.daily;const wx=weather?weatherLabel(weather.weather_code):null;let advice=seasonal[new Date().getMonth()][0];if(forecast){const min=Math.min(...forecast.temperature_2m_min.slice(0,3)),rain=forecast.precipitation_sum.slice(0,3).reduce((a,b)=>a+Number(b||0),0);if(min<=0)advice='Gel possible : surveillez les plantes fragiles et les pots exposés.';else if(rain>=8)advice='Pluie prévue : contrôlez la terre avant d’arroser.';else if(Math.max(...forecast.temperature_2m_max.slice(0,3))>=30)advice='Chaleur annoncée : vérifiez les besoins en eau des jeunes plantations.'}const taskName=t=>t.name||t.title||'Travail de jardin';return `<section class="dashboard-intro"><div><span class="dashboard-eyebrow">🌱 MON JARDIN AUJOURD’HUI</span><h2>Bienvenue dans votre jardin</h2><p class="muted">Votre tableau de bord personnel · ${esc(new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}))}</p></div><div class="actions"><button class="primary" data-action="add-plant">+ Ajouter une plante</button><button data-action="scan">📸 Identifier une plante</button></div></section><div class="dashboard-stats"><div class="card dashboard-stat"><span>🌿 Mes plantes</span><strong>${state.plants.length}</strong><button data-action="plants">Voir mes plantes</button></div><div class="card dashboard-stat"><span>🔔 À faire</span><strong>${due.length}</strong><button data-action="reminders">Voir les rappels</button></div><div class="card dashboard-stat"><span>📅 Travaux du mois</span><strong>${tasks.length}</strong><button data-action="calendar">Voir le calendrier</button></div></div><div class="dashboard-columns"><section class="card dashboard-weather"><div class="row"><h3>🌦️ Météo à Villiers-sur-Loir</h3><button data-action="weather">Détails</button></div>${weather?`<div class="dashboard-temperature">${wx[0]} ${Math.round(weather.temperature_2m)} °C</div><p>${esc(wx[1])} · Vent ${Math.round(weather.wind_speed_10m)} km/h</p><p class="muted">Prévisions indicatives · ${esc(new Date(weatherData.fetchedAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}))}</p>`:weatherLoading?'<p>Chargement de la météo…</p>':`<p class="muted">${weatherError?'Prévisions temporairement indisponibles.':'Chargement des prévisions locales…'}</p><button data-action="home-weather-retry">Réessayer</button>`}</section><section class="card"><div class="row"><h3>🔔 Mes rappels</h3><button data-action="reminders">Tout voir</button></div>${due.length?due.slice(0,3).map(r=>`<div class="dashboard-list-item"><span><strong>${esc(r.type)}</strong><small>${esc(state.plants.find(p=>p.id===r.plantId)?.name||'Plante supprimée')} · ${esc(r.date)}</small></span><span class="pill">${r.date<today?'En retard':'Aujourd’hui'}</span></div>`).join(''):`<p class="muted">Aucun rappel en retard ou prévu aujourd’hui.</p>${upcoming[0]?'<p>Prochain rappel : '+esc(upcoming[0].date)+'</p>':''}`}</section><section class="card"><div class="row"><h3>✂️ Travaux à venir</h3><button data-action="calendar">Calendrier</button></div>${tasks.length?tasks.slice(0,4).map(t=>`<div class="dashboard-list-item"><span>${esc(taskName(t))}</span></div>`).join(''):'<p class="muted">Tous les travaux affichés pour ce mois sont cochés.</p>'}</section><section class="card dashboard-tip"><div class="row"><h3>💡 Conseil du jardin</h3><button data-action="assistant">Assistant</button></div><p>${esc(advice)}</p><p class="muted">Conseil indicatif : adaptez-le à votre sol et à vos plantes.</p></section></div><div class="row"><h2>🌼 Mes dernières plantes</h2><button data-action="plants">Toutes les plantes</button></div><div class="grid">${state.plants.slice(-3).reverse().map(plantCard).join('')||'<p class="muted">Ajoutez votre première plante pour commencer.</p>'}</div>`}
function plantCard(p){return `<article class="card"><div class="plant-emoji botanical-photo" data-photo="${esc(p.name)}">${esc(p.emoji||'🌱')}</div><h3>${esc(p.name)}</h3><span class="pill">${esc(p.zone)}</span><p class="muted">☀ ${esc(p.exposure||'À préciser')}</p><button data-action="detail" data-id="${esc(p.id)}">Voir la fiche</button></article>`}
function plants(){return `<div class="actions"><button class="primary" data-action="scan">📸 Identifier une plante</button><button class="primary" data-action="catalog">🌿 Parcourir le catalogue de 50 plantes</button></div><div class="row"><h2>Mes plantes</h2><button class="primary" data-action="add-plant">+ Ajouter</button></div><div class="card"><label for="search">Rechercher une plante</label><input id="search" placeholder="Nom ou emplacement" autocomplete="off"></div><div class="grid" id="plant-list">${state.plants.map(plantCard).join('')||'<p class="empty">Ajoutez votre première plante.</p>'}</div>`}
function plantForm(p={}){return `<h2>${p.id?'Modifier':'Ajouter'} une plante</h2><form id="plant-form" class="card"><label for="name">Nom *</label><input id="name" name="name" required maxlength="80" value="${esc(p.name||'')}"><label for="zone">Zone</label><select id="zone" name="zone">${state.zoneNames.map(z=>`<option ${p.zone===z?'selected':''}>${esc(z)}</option>`).join('')}</select><label for="emoji">Icône</label><select id="emoji" name="emoji">${['🌱','🌸','🌺','🌳','🍅','🥬','🌹','🪴','🍋','🌿'].map(e=>`<option ${p.emoji===e?'selected':''}>${e}</option>`).join('')}</select><label for="exposure">Exposition</label><select id="exposure" name="exposure">${['À préciser','Soleil','Mi-ombre','Ombre'].map(x=>`<option ${p.exposure===x?'selected':''}>${x}</option>`).join('')}</select><label for="watering">Arrosage</label><select id="watering" name="watering">${['À préciser','Faible','Modéré','Régulier','Sol frais'].map(x=>`<option ${p.watering===x?'selected':''}>${x}</option>`).join('')}</select><label for="notes">Notes et conseils personnels</label><textarea id="notes" name="notes" maxlength="2000">${esc(p.notes||'')}</textarea><div class="actions"><button class="primary" type="submit">Enregistrer</button><button type="button" data-action="plants">Annuler</button></div></form>`}
function detail(p){return `<button data-action="plants">← Mes plantes</button><div class="card"><div class="plant-emoji botanical-photo large" data-photo="${esc(p.name)}">${esc(p.emoji||'🌱')}</div><h2>${esc(p.name)}</h2><button data-action="plant-botanical" data-id="${esc(p.id)}">📖 Fiche botanique complète</button><button data-action="journal" data-id="${esc(p.id)}">📸 Carnet de suivi</button><p>📍 <strong>Zone :</strong> ${esc(p.zone)}</p><p>☀️ <strong>Exposition :</strong> ${esc(p.exposure||'À préciser')}</p><p>💧 <strong>Arrosage :</strong> ${esc(p.watering||'À préciser')}</p><h3>Notes</h3><p>${esc(p.notes||'Aucune note.').replace(/\n/g,'<br>')}</p><div class="actions"><button class="primary" data-action="edit-plant" data-id="${esc(p.id)}">Modifier</button><button class="danger" data-action="delete-plant" data-id="${esc(p.id)}">Supprimer</button></div></div>${carePanel(p)}`}
function calendar(){const list=taskList();return `<div class="row"><h2>Calendrier des travaux</h2><button class="primary" data-action="add-task">+ Travail</button></div><div class="card row"><button data-action="prev-month">←</button><strong>${months[month]} ${year}</strong><button data-action="next-month">→</button></div><div class="card"><p class="muted">Conseils de saison et travaux personnels</p>${list.map(t=>`<div class="task"><input type="checkbox" aria-label="Terminer ${esc(t.name)}" data-task="${esc(t.id)}" ${state.done.includes(t.id)?'checked':''}><div style="flex:1"><div class="${state.done.includes(t.id)?'done':''}">${esc(t.name)}</div><small class="muted">${esc(t.zone)}</small></div>${t.id.startsWith('season-')?'':`<button class="danger" data-action="delete-task" data-id="${esc(t.id)}">×</button>`}</div>`).join('')||'<p>Aucun travail prévu.</p>'}</div>`}
function taskForm(){return `<h2>Ajouter un travail</h2><form id="task-form" class="card"><label for="task-name">Travail à effectuer *</label><input id="task-name" name="name" required maxlength="120"><label for="task-zone">Zone</label><select name="zone" id="task-zone">${state.zoneNames.map(z=>`<option>${esc(z)}</option>`).join('')}</select><label for="task-month">Mois prévu</label><input id="task-month" name="month" type="month" required value="${year}-${String(month+1).padStart(2,'0')}"><div class="actions"><button class="primary" type="submit">Enregistrer</button><button type="button" data-action="calendar">Annuler</button></div></form>`}
let mapSelected=null,mapMode='plant',mapBrush='grass';
const terrainTypes={grass:['🌱','Pelouse'],path:['🟫','Allée'],terrace:['🪵','Terrasse'],vegetable:['🥬','Potager'],flower:['🌺','Massif'],water:['💧','Bassin'],soil:['🟤','Terre'],erase:['✖','Effacer']};
function map(){const pos=state.mapPositions||{},terrain=state.mapTerrain||{},selectedPlant=state.plants.find(p=>p.id===mapSelected),entries=Object.entries(pos).filter(([id])=>state.plants.some(p=>p.id===id));return `<h2>🏡 Mon jardin personnalisable</h2><p class="muted">Dessinez les espaces du jardin puis placez vos plantes. Touchez les cases pour modifier le plan.</p><div class="card"><div class="map-mode"><button data-action="map-mode" data-id="terrain" class="${mapMode==='terrain'?'primary':''}">🎨 Aménager</button><button data-action="map-mode" data-id="plant" class="${mapMode==='plant'?'primary':''}">🌿 Placer les plantes</button></div>${mapMode==='terrain'?`<label for="map-brush">Élément à dessiner</label><select id="map-brush">${Object.entries(terrainTypes).map(([key,val])=>`<option value="${key}" ${mapBrush===key?'selected':''}>${val[0]} ${val[1]}</option>`).join('')}</select><p class="muted">Choisissez un élément, puis touchez les cases à colorier. « Effacer » retire l'aménagement d'une case sans retirer les plantes.</p>`:`<label for="map-plant">Plante à positionner</label><select id="map-plant"><option value="">— Choisir une plante —</option>${state.plants.map(p=>`<option value="${esc(p.id)}" ${mapSelected===p.id?'selected':''}>${esc(p.name)} (${esc(p.zone)})</option>`).join('')}</select><p class="muted">${selectedPlant?'Touchez une case pour placer '+esc(selectedPlant.name):'Choisissez une plante puis touchez une case.'}</p>`}<div class="garden-grid" role="group" aria-label="Plan du jardin, 8 colonnes et 6 lignes">${Array.from({length:48},(_,i)=>{const here=entries.filter(([,v])=>v===i).map(([id])=>state.plants.find(p=>p.id===id)).filter(Boolean),type=terrain[i],label=terrainTypes[type]?.[1]||'Non aménagé';return `<button type="button" class="garden-cell terrain-${type||'none'} ${here.length?'occupied':''}" data-action="map-cell" data-id="${i}" aria-label="Case ${i+1}, ${label}, ${here.map(p=>p.name).join(', ')||'sans plante'}" title="${esc(label+' · '+here.map(p=>p.name).join(', '))}">${here.length?here.slice(0,2).map(p=>`<span>${esc(p.emoji||'🌱')}</span>`).join('')+(here.length>2?'<small>+'+(here.length-2)+'</small>':''):`<span class="terrain-icon">${terrainTypes[type]?.[0]||''}</span>`}</button>`}).join('')}</div><div class="actions">${mapMode==='plant'? `<button data-action="map-remove" ${!selectedPlant||pos[mapSelected]===undefined?'disabled':''}>Retirer la plante sélectionnée du plan</button>`:`<button data-action="map-clear-terrain">Effacer tous les aménagements</button>`}</div></div><h3>Plantes positionnées (${entries.length}/${state.plants.length})</h3><div class="card">${entries.length?entries.map(([id,cell])=>{const p=state.plants.find(p=>p.id===id);return `<div class="task"><span>${esc(p.emoji||'🌱')}</span><div style="flex:1">${esc(p.name)} <small class="muted">· Ligne ${Math.floor(cell/8)+1}, colonne ${cell%8+1}</small></div><button data-action="detail" data-id="${esc(id)}">Fiche</button></div>`}).join(''):'<p class="muted">Aucune plante positionnée pour le moment.</p>'}</div><h3>Mes zones</h3><div class="zones">${state.zoneNames.map((z,i)=>`<div class="zone"><span>${['🌺','🥬','🌳','🪴'][i%4]}</span><strong>${esc(z)}</strong><small>${state.plants.filter(p=>p.zone===z).length} plante(s)</small><div class="actions" style="justify-content:center"><button data-action="zone" data-id="${esc(z)}">Voir</button></div></div>`).join('')}</div>`}
function zoneView(z){return `<button data-action="map">← Retour au plan</button><h2>${esc(z)}</h2><div class="grid">${state.plants.filter(p=>p.zone===z).map(plantCard).join('')||'<p class="empty">Aucune plante dans cette zone.</p>'}</div>`}

function backupDownload(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function blobToDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
function dataURLToBlob(value){if(typeof value!=='string'||!/^data:image\/(jpeg|png|webp);base64,[a-zA-Z0-9+/=]+$/.test(value))throw Error('Photo de sauvegarde invalide');const [head,base64]=value.split(','),binary=atob(base64),arr=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)arr[i]=binary.charCodeAt(i);return new Blob([arr],{type:head.slice(5,head.indexOf(';'))})}
async function exportFullBackup(){const entries=(state.journal||[]).filter(x=>x.hasPhoto),photos={};for(const item of entries){const blob=await getJournalPhoto(item.id);if(!blob)throw Error('La photo de l’observation du '+item.date+' est introuvable. Export annulé pour éviter une sauvegarde incomplète.');photos[item.id]=await blobToDataURL(blob)}const data={version:2,createdAt:new Date().toISOString(),...state,photos};const blob=new Blob([JSON.stringify(data)],{type:'application/json'});backupDownload(blob,'jardeo-complet-'+new Date().toISOString().slice(0,10)+'.json');alert('Sauvegarde complète préparée : '+entries.length+' photo(s). Conservez le fichier téléchargé en lieu sûr.')}
function validateBackup(x){if(!x||x.reminders!==undefined&&!Array.isArray(x.reminders)||!Array.isArray(x.plants)||!Array.isArray(x.tasks)||!Array.isArray(x.done)||!Array.isArray(x.zoneNames)||!x.plants.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&typeof p.zone==='string')||!x.tasks.every(t=>typeof t.id==='string'&&typeof t.name==='string'&&typeof t.month==='string')||!x.zoneNames.every(z=>typeof z==='string')||x.journal!==undefined&&!Array.isArray(x.journal))throw Error('Format de sauvegarde invalide');if(x.photos!==undefined&&(typeof x.photos!=='object'||!x.photos||Array.isArray(x.photos)))throw Error('Photos de sauvegarde invalides');return x}
async function restoreFullBackup(file){if(file.size>100e6)throw Error('Fichier trop volumineux (100 Mo maximum).');const x=validateBackup(JSON.parse(await file.text()));const incoming=Array.isArray(x.journal)?x.journal:[];const photos=x.photos||{};const blobs={};for(const item of incoming){if(item.hasPhoto){if(photos[item.id])blobs[item.id]=dataURLToBlob(photos[item.id]);else if(x.version>=2)throw Error('Photo manquante dans la sauvegarde : '+item.id)}}if(!confirm('Remplacer toutes les données de JARDÉO sur cet appareil par cette sauvegarde ? Pensez à exporter vos données actuelles avant de continuer.'))return;const oldState=state;const db=await journalDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite'),store=tx.objectStore('photos');store.clear();Object.entries(blobs).forEach(([id,blob])=>store.put(blob,id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});const next={plants:x.plants,tasks:x.tasks,done:x.done,zoneNames:x.zoneNames,mapPositions:x.mapPositions&&typeof x.mapPositions==='object'?x.mapPositions:{},mapTerrain:x.mapTerrain&&typeof x.mapTerrain==='object'?x.mapTerrain:{},journal:incoming.map(item=>({...item,hasPhoto:!!blobs[item.id]})),plantingDates:x.plantingDates&&typeof x.plantingDates==='object'?x.plantingDates:{},reminders:Array.isArray(x.reminders)?x.reminders:[]};state=next;if(!save())throw Error('Impossible d’enregistrer la restauration.');go('home');alert('Restauration terminée : '+Object.keys(blobs).length+' photo(s) restaurée(s).')}catch(e){state=oldState;throw e}finally{db.close()}}


let scanResults=[],scanBusy=false,scanMessage='',scanPreview='';
function scanView(){const key=sessionStorage.getItem('jardeo-plantnet-key')||'';return `<div class="row"><h2>📸 Identifier une plante</h2><button data-action="plants">Mes plantes</button></div><p class="muted">Prenez une photo nette d’une feuille, fleur ou plante entière. L’identification est une proposition, pas une certitude.</p><div class="card"><h3>1. Configurer la reconnaissance gratuite</h3><p>JARDÉO utilise l’API Pl@ntNet. Un compte et une clé API gratuits sont nécessaires.</p><p><a href="https://my.plantnet.org/" target="_blank" rel="noopener noreferrer">Créer mon compte Pl@ntNet ↗</a></p><label for="scan-key">Clé API Pl@ntNet</label><input id="scan-key" type="password" autocomplete="off" placeholder="Coller votre clé API" value="${esc(key)}"><p class="muted">Dans Pl@ntNet, autorisez l’accès navigateur (CORS) et le domaine <strong>https://olivicas.github.io</strong>. La clé est conservée uniquement pendant cette session, jamais publiée sur GitHub ni incluse dans les sauvegardes. Elle reste accessible aux scripts exécutés dans cette page.</p></div><form id="scan-form" class="card"><h3>2. Photographier la plante</h3><label for="scan-photo">Photo de la plante</label><input id="scan-photo" type="file" accept="image/jpeg,image/png,image/*" capture="environment" required><p class="muted">Sur téléphone, vous pouvez prendre une photo ou sélectionner une image. Une fleur bien visible améliore souvent le résultat.</p>${scanPreview?'<div class="scan-preview"><img src="'+scanPreview+'" alt="Photo à identifier"></div>':''}<button class="primary" type="submit" ${scanBusy?'disabled':''}>${scanBusy?'Identification en cours…':'🔎 Identifier ma plante'}</button></form>${scanMessage?'<div class="card notice" role="status">'+esc(scanMessage)+'</div>':''}${scanResults.length?'<h3>3. Résultats proposés</h3><div class="grid">'+scanResults.map((r,i)=>{const n=r.species?.commonNames?.[0]||r.species?.scientificNameWithoutAuthor||'Espèce inconnue',scientific=r.species?.scientificNameWithoutAuthor||r.species?.scientificName||'',pct=Math.round((r.score||0)*100);const match=catalog.find(p=>p.name.toLocaleLowerCase('fr')===n.toLocaleLowerCase('fr')||p.name.toLocaleLowerCase('fr')===scientific.toLocaleLowerCase('fr'));return '<article class="card"><h3>'+esc(n)+'</h3><p class="muted"><i>'+esc(scientific)+'</i></p><span class="pill">Confiance indicative : '+pct+' %</span><p>'+(match?'Fiche d’entretien du catalogue JARDÉO disponible.':'Fiche détaillée non disponible dans le catalogue local.')+'</p>'+carePanel({name:n,scientificName:scientific})+'<button class="primary" data-action="scan-add" data-id="'+i+'">+ Ajouter à mon jardin</button></article>'}).join('')+'</div><p class="muted">Les scores ne garantissent pas l’identification. Confirmez l’espèce avant tout usage alimentaire ou médicinal.</p>':''}<p class="muted">Reconnaissance fournie par <a href="https://my.plantnet.org/" target="_blank" rel="noopener noreferrer">Pl@ntNet</a>. Une connexion Internet est nécessaire pour analyser la photo.</p>`}
async function identifyPlant(file,key){if(!file||!file.type.startsWith('image/')||file.size>15*1024*1024)throw Error('Choisissez une photo JPG/PNG de moins de 15 Mo.');const data=new FormData();data.append('images',file,file.name||'plante.jpg');const response=await fetch('https://my-api.plantnet.org/v2/identify/all?lang=fr&api-key='+encodeURIComponent(key),{method:'POST',body:data});if(!response.ok){if(response.status===401||response.status===403)throw Error('Clé refusée : vérifiez la clé, l’option CORS et le domaine autorisé dans Pl@ntNet.');if(response.status===429)throw Error('Quota de reconnaissance atteint. Réessayez plus tard.');throw Error('Identification indisponible (erreur '+response.status+').')}const json=await response.json();if(!Array.isArray(json.results)||!json.results.length)throw Error('Aucune plante reconnue. Essayez une photo plus nette.');return json.results.slice(0,3)}
function settings(){return `<h2>Mes données</h2><div class="card"><h3>💾 Sauvegarde complète</h3><p>Enregistrez vos plantes, le plan, le calendrier, le carnet et les photos dans un fichier JSON. Gardez-le en lieu sûr pour changer de téléphone.</p><div class="actions"><button class="primary" data-action="export">📦 Télécharger ma sauvegarde complète</button><button data-action="import">📂 Restaurer une sauvegarde</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><p class="muted">La restauration remplace les données présentes sur cet appareil. Les anciennes sauvegardes sans photos restent acceptées.</p></div><div class="card"><h3>Remettre à zéro</h3><p class="muted">Supprime les plantes et tâches personnelles de cet appareil.</p><button class="danger" data-action="reset">Effacer mes données</button></div>`}
let weatherData=null,weatherError='',weatherLoading=false;
function weatherLabel(code){if(code===0)return ['☀️','Ensoleillé'];if([1,2].includes(code))return ['🌤️','Éclaircies'];if(code===3)return ['☁️','Couvert'];if([45,48].includes(code))return ['🌫️','Brouillard'];if([51,53,55,56,57].includes(code))return ['🌦️','Bruine'];if([61,63,65,66,67,80,81,82].includes(code))return ['🌧️','Pluie'];if([71,73,75,77,85,86].includes(code))return ['❄️','Neige'];if([95,96,99].includes(code))return ['⛈️','Orage'];return ['🌡️','Conditions variables']}
function weatherAdvice(d){const out=[];const mins=d.temperature_2m_min||[],rain=d.precipitation_sum||[],maxs=d.temperature_2m_max||[];if(mins.some(x=>Number.isFinite(x)&&x<=0))out.push('❄️ Gel possible dans les prochains jours : protégez les plantes sensibles et les pots exposés.');else if(mins.some(x=>Number.isFinite(x)&&x<=3))out.push('🧣 Nuits fraîches annoncées : surveillez les plantes fragiles, surtout en pot.');if(rain.slice(0,3).some(x=>x>=5))out.push('🌧️ Pluie prévue : vérifiez la terre avant d’arroser et évitez les arrosages automatiques inutiles.');else if(rain.slice(0,3).every(x=>x<1)&&maxs.slice(0,3).some(x=>x>=25))out.push('💧 Temps chaud et peu pluvieux : contrôlez l’humidité du sol et arrosez au pied si nécessaire.');if(maxs.some(x=>x>=32))out.push('☀️ Forte chaleur possible : protégez les jeunes plantations du soleil direct.');if(!out.length)out.push('🌱 Pas de risque météo majeur identifié dans ces prévisions. Surveillez tout de même le sol et les plantes sensibles.');return out}
function weatherView(){if(weatherLoading)return '<h2>🌦️ Météo du jardin</h2><div class="card">Chargement des prévisions pour Villiers-sur-Loir…</div>';if(weatherError)return '<h2>🌦️ Météo du jardin</h2><div class="card"><p>Impossible de charger les prévisions : '+esc(weatherError)+'</p><button data-action="weather-retry">Réessayer</button></div>';if(!weatherData)return '<h2>🌦️ Météo du jardin</h2><div class="card"><button class="primary" data-action="weather-retry">Afficher la météo</button></div>';const w=weatherData,c=w.current,d=w.daily,desc=weatherLabel(c.weather_code);return `<h2>🌦️ Météo du jardin</h2><p class="muted">Villiers-sur-Loir (41) · Prévisions indicatives mises à jour : ${esc(new Date(w.fetchedAt).toLocaleString('fr-FR'))}</p><div class="card"><div class="row"><div><div class="big">${desc[0]} ${Math.round(c.temperature_2m)} °C</div><strong>${desc[1]}</strong></div><div>💨 Vent : ${Math.round(c.wind_speed_10m)} km/h<br>💧 Humidité : ${Math.round(c.relative_humidity_2m)} %</div></div></div><h3>Prévisions sur 7 jours</h3><div class="weather-days">${d.time.map((day,i)=>`<article class="weather-day"><strong>${esc(new Date(day+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short',day:'numeric'}))}</strong><div class="weather-icon">${weatherLabel(d.weather_code[i])[0]}</div><span>${Math.round(d.temperature_2m_min[i])}° / ${Math.round(d.temperature_2m_max[i])}°</span><small>🌧️ ${Math.round(d.precipitation_probability_max[i]||0)} %</small><small>${Number(d.precipitation_sum[i]||0).toLocaleString('fr-FR')} mm</small></article>`).join('')}</div><h3>Conseils pour mon jardin</h3><div class="card">${weatherAdvice(d).map(x=>'<p>'+esc(x)+'</p>').join('')}</div><div class="actions"><button data-action="weather-retry">🔄 Actualiser les prévisions</button></div><p class="muted">Données : <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a>. Les prévisions ne constituent pas une alerte officielle et peuvent évoluer. En cas de vigilance météo, consultez Météo-France.</p>`}
async function loadWeather(force=false){if(weatherLoading)return;if(!force&&weatherData&&Date.now()-weatherData.fetchedAt<30*60*1000){render();return}weatherLoading=true;weatherError='';render();try{const geo=await fetch('https://geocoding-api.open-meteo.com/v1/search?name=Villiers-sur-Loir&count=10&language=fr&format=json');if(!geo.ok)throw Error('localisation indisponible');const places=(await geo.json()).results||[];const place=places.find(p=>p.country_code==='FR'&&p.name.toLowerCase().includes('villiers-sur-loir'))||places.find(p=>p.country_code==='FR');if(!place)throw Error('commune introuvable');const url='https://api.open-meteo.com/v1/forecast?latitude='+place.latitude+'&longitude='+place.longitude+'&current=temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max&timezone=Europe%2FParis&forecast_days=7';const res=await fetch(url);if(!res.ok)throw Error('service météo indisponible');const data=await res.json();if(!data.current||!data.daily?.time)throw Error('prévisions incomplètes');weatherData={...data,fetchedAt:Date.now()}}catch(e){weatherError=e.message||'connexion indisponible'}finally{weatherLoading=false;if(['home','weather','assistant'].includes(view))render()}}


function assistantView(){const plants=state.plants||[],d=weatherData?.daily,notes=[],today=new Date(),thisMonth=today.getMonth(),thisYear=today.getFullYear();const names=plants.map(p=>p.name.toLocaleLowerCase('fr'));const vulnerable=['citronnier','kumquat','laurier-rose','mimosa','bougainvillier','basilic','tomate','poivron','aubergine','oranger'];const sensitive=plants.filter(p=>vulnerable.some(n=>p.name.toLocaleLowerCase('fr').includes(n)));const pnames=arr=>arr.slice(0,5).map(p=>p.name).join(', ')+(arr.length>5?'…':'');if(d){const min=Math.min(...d.temperature_2m_min.slice(0,4)),max=Math.max(...d.temperature_2m_max.slice(0,4)),rain=d.precipitation_sum.slice(0,3).reduce((a,b)=>a+Number(b||0),0);if(min<=2){notes.push({level:'urgent',icon:'❄️',title:min<=0?'Risque de gel':'Nuits froides',body:sensitive.length?'Température minimale prévue : '+Math.round(min)+' °C. Surveillez et protégez selon leur rusticité : '+pnames(sensitive)+'. Les plantes en pot sont particulièrement exposées.':'Température minimale prévue : '+Math.round(min)+' °C. Surveillez les jeunes plantations et les plantes sensibles au froid.'})}if(rain>=8)notes.push({level:'info',icon:'🌧️',title:'Pluie prévue',body:'Environ '+rain.toFixed(1)+' mm cumulés prévus sur trois jours. Vérifiez l’humidité du sol avant d’arroser ; évitez les arrosages inutiles.'});else if(rain<2&&max>=25)notes.push({level:'warning',icon:'💧',title:'Surveiller l’arrosage',body:'Peu de pluie prévue et jusqu’à '+Math.round(max)+' °C. Vérifiez la terre au pied des plantes, surtout les pots et jeunes plantations.'});if(max>=32)notes.push({level:'warning',icon:'☀️',title:'Fortes chaleurs possibles',body:'Des maximales proches de '+Math.round(max)+' °C sont prévues. Paillez si nécessaire et protégez les jeunes plants.'})}else notes.push({level:'info',icon:'🌦️',title:'Météo non chargée',body:'Chargez les prévisions pour obtenir des conseils liés au gel, à la pluie et à la chaleur.'});const work=taskList().filter(t=>!state.done.includes(t.id)).slice(0,5);if(month!==thisMonth||year!==thisYear){notes.push({level:'info',icon:'📅',title:'Calendrier affiché sur un autre mois',body:'L’assistant utilise le mois actuellement sélectionné dans le calendrier : '+months[month]+' '+year+'.'})}if(work.length)notes.push({level:'info',icon:'✂️',title:'Travaux à prévoir',body:'Vous avez '+taskList().filter(t=>!state.done.includes(t.id)).length+' travaux non cochés pour '+months[month]+'.',items:work.map(t=>t.name||t.title||'Travail de jardin')});if(!plants.length)notes.push({level:'info',icon:'🌱',title:'Ajoutez vos plantes',body:'Enregistrez quelques plantes pour recevoir des recommandations plus ciblées.'});if(!notes.length)notes.push({level:'info',icon:'🌿',title:'Jardin à surveiller',body:'Pas de priorité particulière détectée. Observez vos plantes et l’humidité du sol.'});return `<h2>🌿 Mon assistant jardin</h2><p class="muted">Conseils calculés à partir de ${plants.length} plante(s), de votre calendrier et des prévisions locales de Villiers-sur-Loir.</p><div class="actions"><button class="primary" data-action="assistant-refresh">🔄 Actualiser météo et conseils</button><button data-action="calendar">Voir le calendrier</button></div>${weatherLoading?'<p class="muted">Actualisation météo en cours…</p>':''}${weatherError?'<p class="muted">Météo indisponible : '+esc(weatherError)+'</p>':''}<div class="assistant-cards">${notes.map(n=>`<article class="card assistant-card ${n.level}"><h3>${n.icon} ${esc(n.title)}</h3><p>${esc(n.body)}</p>${n.items?'<ul>'+n.items.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':''}</article>`).join('')}</div><p class="muted">Ces conseils sont indicatifs et ne tiennent pas compte de l’humidité réelle du sol, de l’exposition précise ou de la rusticité de chaque variété. Consultez les vigilances officielles en cas d’intempéries.</p>`}


const journalPhotos=new Map();
function journalDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('jardeo-photos',1);req.onupgradeneeded=()=>req.result.createObjectStore('photos');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function storeJournalPhoto(id,file){if(!file.type.startsWith('image/'))throw Error('Sélectionnez une image.');if(file.size>12e6)throw Error('Photo trop volumineuse (12 Mo maximum).');const bmp=await createImageBitmap(file);const scale=Math.min(1,1000/Math.max(bmp.width,bmp.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bmp.width*scale));canvas.height=Math.max(1,Math.round(bmp.height*scale));canvas.getContext('2d').drawImage(bmp,0,0,canvas.width,canvas.height);bmp.close();const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.75));if(!blob)throw Error('Conversion de photo impossible.');const db=await journalDB();await new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function getJournalPhoto(id){const db=await journalDB();const blob=await new Promise((resolve,reject)=>{const tx=db.transaction('photos','readonly'),req=tx.objectStore('photos').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return blob}
async function removeJournalPhoto(id){const db=await journalDB();await new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function showJournalPhotos(){document.querySelectorAll('[data-journal-photo]').forEach(async el=>{try{const blob=await getJournalPhoto(el.dataset.journalPhoto);if(!blob||!el.isConnected)return;const url=URL.createObjectURL(blob),img=document.createElement('img');img.src=url;img.alt='Photo personnelle du jardin';img.loading='lazy';img.onload=()=>URL.revokeObjectURL(url);img.onerror=()=>URL.revokeObjectURL(url);el.replaceChildren(img)}catch(e){}})}
function journalView(p){const all=(state.journal||[]).filter(x=>x.plantId===p.id).sort((a,b)=>b.date.localeCompare(a.date));const planted=state.plantingDates?.[p.id]||'';return `<button data-action="detail" data-id="${esc(p.id)}">← Fiche de la plante</button><h2>📸 Carnet : ${esc(p.name)}</h2><div class="card"><form id="planting-form"><input type="hidden" name="plantId" value="${esc(p.id)}"><label for="planting-date">Date de plantation</label><input type="date" id="planting-date" name="date" value="${esc(planted)}"><button class="primary" type="submit">Enregistrer la date</button></form></div><div class="card"><h3>Ajouter une observation</h3><form id="journal-form"><input type="hidden" name="plantId" value="${esc(p.id)}"><label for="journal-date">Date</label><input id="journal-date" name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required><label for="journal-note">Note d'entretien ou de croissance</label><textarea id="journal-note" name="note" maxlength="1000" placeholder="Arrosage, floraison, croissance, taille…" required></textarea><label for="journal-photo">Photo facultative</label><input id="journal-photo" name="photo" type="file" accept="image/*"><p class="muted">Les photos sont conservées sur cet appareil, séparément de la sauvegarde JSON.</p><button class="primary" type="submit">Ajouter au carnet</button></form></div><h3>Historique (${all.length})</h3>${all.map(x=>`<article class="card"><div class="row"><strong>${esc(x.date)}</strong><button data-action="journal-delete" data-id="${esc(x.id)}">Supprimer</button></div><p>${esc(x.note)}</p>${x.hasPhoto?'<div class="journal-photo" data-journal-photo="'+esc(x.id)+'">📸 Chargement…</div>':''}</article>`).join('')||'<p class="muted">Aucune observation pour cette plante.</p>'}`}


function localDateISO(date=new Date()){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return y+'-'+m+'-'+d}
function advanceReminderDate(date,days){const [y,m,d]=date.split('-').map(Number),next=new Date(y,m-1,d,12);next.setDate(next.getDate()+days);return localDateISO(next)}
function reminderStatus(r){const today=localDateISO();return r.date<today?'En retard':r.date===today?"Aujourd’hui":'À venir'}
function reminderView(){const all=[...(state.reminders||[])].sort((a,b)=>a.date.localeCompare(b.date)),today=localDateISO(),due=all.filter(r=>r.date<=today);return `<div class="row"><h2>🔔 Mes rappels</h2><button class="primary" data-action="reminder-add">+ Rappel</button></div><p class="muted">Rappels visibles à l’ouverture de JARDÉO. Pas encore de notification lorsque l’application est fermée.</p><div class="card"><strong>${due.length} rappel(s) à faire</strong><p class="muted">Les rappels récurrents passent à leur prochaine date lorsque vous les validez.</p></div>${all.map(r=>{const plant=state.plants.find(p=>p.id===r.plantId);return `<article class="card reminder-item"><div class="row"><h3>${esc(r.type)} · ${esc(plant?.name||'Plante supprimée')}</h3><span class="pill">${esc(reminderStatus(r))}</span></div><p>📅 ${esc(r.date)} ${r.every?'· Tous les '+r.every+' jours':'· Une seule fois'}</p>${r.note?'<p>'+esc(r.note)+'</p>':''}<div class="actions"><button class="primary" data-action="reminder-done" data-id="${esc(r.id)}">✓ Terminé</button><button class="danger" data-action="reminder-delete" data-id="${esc(r.id)}">Supprimer</button></div></article>`}).join('')||'<p class="muted">Aucun rappel enregistré. Ajoutez-en un pour commencer.</p>'}`}
function reminderForm(){return `<button data-action="reminders">← Mes rappels</button><h2>Ajouter un rappel</h2><form id="reminder-form" class="card"><label for="reminder-plant">Plante</label><select id="reminder-plant" name="plantId" required>${state.plants.map(p=>`<option value="${esc(p.id)}" ${p.id===editing?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label for="reminder-type">Entretien</label><select id="reminder-type" name="type">${['Arrosage','Taille','Fertilisation','Rempotage','Autre entretien'].map(t=>'<option>'+t+'</option>').join('')}</select><label for="reminder-date">Date du prochain rappel</label><input id="reminder-date" type="date" name="date" value="${localDateISO()}" required><label for="reminder-repeat">Répétition</label><select id="reminder-repeat" name="every"><option value="0">Une seule fois</option><option value="1">Chaque jour</option><option value="3">Tous les 3 jours</option><option value="7">Chaque semaine</option><option value="14">Tous les 14 jours</option><option value="30">Tous les 30 jours</option><option value="90">Tous les 90 jours</option><option value="365">Tous les 365 jours</option></select><label for="reminder-note">Note facultative</label><textarea id="reminder-note" name="note" maxlength="500" placeholder="Ex. Vérifier que le terreau est sec avant d’arroser"></textarea><button class="primary" type="submit" ${state.plants.length?'':'disabled'}>Enregistrer</button>${state.plants.length?'':'<p>Ajoutez d’abord une plante dans la rubrique Plantes.</p>'}</form>`}

function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const m=$('#main');if(view==='home')m.innerHTML=home();else if(view==='plants')m.innerHTML=plants();else if(view==='catalog')m.innerHTML=catalogView();else if(view==='catalog-detail')m.innerHTML=botanicalDetail(catalog[Number(editing)],'catalog');else if(view==='plant-botanical')m.innerHTML=botanicalDetail(state.plants.find(p=>p.id===editing),'plants');else if(view==='form')m.innerHTML=plantForm(editing||{});else if(view==='detail')m.innerHTML=detail(state.plants.find(p=>p.id===editing)||state.plants[0]);else if(view==='calendar')m.innerHTML=calendar();else if(view==='taskform')m.innerHTML=taskForm();else if(view==='map')m.innerHTML=map();else if(view==='weather')m.innerHTML=weatherView();else if(view==='assistant')m.innerHTML=assistantView();else if(view==='reminders')m.innerHTML=reminderView();else if(view==='scan')m.innerHTML=scanView();else if(view==='reminder-form')m.innerHTML=reminderForm();else if(view==='journal')m.innerHTML=journalView(state.plants.find(p=>p.id===editing));else if(view==='zone')m.innerHTML=zoneView(editing);else m.innerHTML=settings();loadBotanicalPhotos();if(view==='journal')showJournalPhotos()}
$('#today').textContent=new Date().toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'});
document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>{go(b.dataset.view);if(['weather','assistant'].includes(b.dataset.view))loadWeather()}));
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(['plants','calendar','map','reminders','weather','assistant','scan'].includes(a)){go(a);if(['weather','assistant'].includes(a))loadWeather();return}if(a==='scan-add'){const r=scanResults[Number(id)];if(!r)return;const scientific=r.species?.scientificNameWithoutAuthor||r.species?.scientificName||'',name=r.species?.commonNames?.[0]||scientific,match=catalog.find(p=>p.name.toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr')||p.name.toLocaleLowerCase('fr')===scientific.toLocaleLowerCase('fr'));const p={id:uid(),name,scientificName:scientific,zone:state.zoneNames[0]||'Jardin',emoji:match?.emoji||'🌱',exposure:match?.exposure||'À préciser',watering:match?.watering||'À préciser',notes:match?.notes||('Identification probable par Pl@ntNet : '+scientific+'. Vérifier l’espèce et ses besoins avant toute intervention.')};state.plants.push(p);save();editing=p.id;view='detail';render();return}if(a==='home-weather-retry'){loadWeather(true);return}if(a==='reminder-add'){editing=null;view='reminder-form';render();return}if(a==='reminder-done'){const r=(state.reminders||[]).find(x=>x.id===id);if(r){if(r.every){const today=localDateISO();let next=r.date;do{next=advanceReminderDate(next,r.every)}while(next<=today);r.date=next}else state.reminders=state.reminders.filter(x=>x.id!==id);save();render()}return}if(a==='reminder-delete'){if(confirm('Supprimer ce rappel ?')){state.reminders=(state.reminders||[]).filter(x=>x.id!==id);save();render()}return}if(a==='weather-retry'||a==='assistant-refresh'){loadWeather(true);return}if(a==='journal'){editing=id;view='journal';render()}else if(a==='journal-delete'){const entry=(state.journal||[]).find(x=>x.id===id);if(entry&&confirm('Supprimer cette observation ?')){state.journal=state.journal.filter(x=>x.id!==id);save();removeJournalPhoto(id).catch(()=>{});render()}}else if(a==='map-mode'){mapMode=id;render()}else if(a==='map-clear-terrain'){if(confirm('Effacer tous les aménagements du plan ? Les plantes resteront en place.')){state.mapTerrain={};save();render()}}else if(a==='map-cell'){if(mapMode==='terrain'){state.mapTerrain=state.mapTerrain||{};if(mapBrush==='erase')delete state.mapTerrain[id];else state.mapTerrain[id]=mapBrush;save();render();return}if(!mapSelected){alert('Choisissez d’abord une plante dans la liste.');return}state.mapPositions=state.mapPositions||{};state.mapPositions[mapSelected]=Number(id);save();render()}else if(a==='map-remove'){if(mapSelected&&state.mapPositions){delete state.mapPositions[mapSelected];save();render()}}else if(a==='catalog'){view='catalog';render()}else if(a==='catalog-detail'){editing=id;view='catalog-detail';render()}else if(a==='plant-botanical'){editing=id;view='plant-botanical';render()}else if(a==='catalog-add'){const p=catalog[Number(id)];if(p){state.plants.push({...p,id:uid()});save();go('plants')}}else if(a==='add-plant'){editing=null;view='form';render()}else if(a==='detail'||a==='edit-plant'){editing=id;view=a==='detail'?'detail':'form';render()}else if(a==='delete-plant'){if(confirm('Supprimer cette plante ?')){state.plants=state.plants.filter(p=>p.id!==id);save();go('plants')}}else if(a==='add-task')go('taskform');else if(a==='delete-task'){if(confirm('Supprimer ce travail ?')){state.tasks=state.tasks.filter(t=>t.id!==id);state.done=state.done.filter(x=>x!==id);save();render()}}else if(a==='prev-month'||a==='next-month'){const d=new Date(year,month+(a==='next-month'?1:-1),1);month=d.getMonth();year=d.getFullYear();render()}else if(a==='zone'){editing=id;view='zone';render()}else if(a==='export'){exportFullBackup().catch(err=>alert('Sauvegarde impossible : '+err.message))}else if(a==='import')$('#import-file').click();else if(a==='reset'&&confirm('Effacer définitivement toutes les données locales de JARDÉO ?')){state={plants:[],tasks:[],done:[],zoneNames:[...defaults.zoneNames]};save();go('home')}});
document.addEventListener('submit',async e=>{if(e.target.id==='scan-form'){e.preventDefault();if(scanBusy)return;const key=String(document.querySelector('#scan-key')?.value||'').trim(),file=document.querySelector('#scan-photo')?.files?.[0];if(!key){scanMessage='Saisissez votre clé API Pl@ntNet avant de lancer la reconnaissance.';render();return}if(!file){scanMessage='Choisissez une photo.';render();return}sessionStorage.setItem('jardeo-plantnet-key',key);scanBusy=true;scanResults=[];scanMessage='Analyse de la photo en cours…';const button=e.target.querySelector('[type=submit]');if(button){button.disabled=true;button.textContent='Identification en cours…'}try{scanResults=await identifyPlant(file,key);scanMessage='Voici les espèces les plus probables. Vérifiez le résultat avant de l’ajouter.'}catch(err){scanMessage=err.message||'Erreur de reconnaissance. Vérifiez la connexion et les paramètres Pl@ntNet.'}finally{scanBusy=false;render()}return}if(e.target.id==='reminder-form'){e.preventDefault();const f=new FormData(e.target),plantId=String(f.get('plantId')),date=String(f.get('date')),every=Number(f.get('every'));if(!state.plants.some(p=>p.id===plantId)||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(date)||![0,1,3,7,14,30,90,365].includes(every))return alert('Rappel invalide.');state.reminders=state.reminders||[];state.reminders.push({id:uid(),plantId,type:String(f.get('type')),date,every,note:String(f.get('note')).trim()});save();go('reminders');return}if(e.target.id==='planting-form'){e.preventDefault();const f=new FormData(e.target);state.plantingDates=state.plantingDates||{};state.plantingDates[String(f.get('plantId'))]=String(f.get('date'));save();render();return}if(e.target.id==='journal-form'){e.preventDefault();const f=new FormData(e.target),file=f.get('photo'),entry={id:uid(),plantId:String(f.get('plantId')),date:String(f.get('date')),note:String(f.get('note')).trim(),hasPhoto:!!file?.size};if(!entry.note)return;try{if(entry.hasPhoto)await storeJournalPhoto(entry.id,file);state.journal=state.journal||[];state.journal.push(entry);save();render()}catch(err){alert('Impossible d’enregistrer la photo : '+err.message)}return}if(e.target.id==='plant-form'){e.preventDefault();const f=new FormData(e.target),p={id:editing||uid(),name:String(f.get('name')).trim(),zone:String(f.get('zone')),emoji:String(f.get('emoji')),exposure:String(f.get('exposure')),watering:String(f.get('watering')),notes:String(f.get('notes')).trim()};if(!p.name)return;if(editing)state.plants=state.plants.map(x=>x.id===editing?p:x);else state.plants.push(p);save();editing=p.id;view='detail';render()}else if(e.target.id==='task-form'){e.preventDefault();const f=new FormData(e.target);state.tasks.push({id:uid(),name:String(f.get('name')).trim(),zone:String(f.get('zone')),month:String(f.get('month'))});save();const [y,m]=String(f.get('month')).split('-').map(Number);year=y;month=m-1;go('calendar')}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-task]')){const id=e.target.dataset.task;state.done=e.target.checked?[...new Set([...state.done,id])]:state.done.filter(x=>x!==id);save();render()}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{await restoreFullBackup(file)}catch(err){alert('Import impossible : '+err.message)}finally{e.target.value=''}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const q=e.target.value.toLocaleLowerCase('fr');$('#plant-list').innerHTML=state.plants.filter(p=>(p.name+' '+p.zone).toLocaleLowerCase('fr').includes(q)).map(plantCard).join('')||'<p>Aucune plante trouvée.</p>'}});
render();if(view==='home')loadWeather();

document.addEventListener('change',e=>{if(e.target.id==='map-brush'){mapBrush=e.target.value;render()}if(e.target.id==='map-plant'){mapSelected=e.target.value||null;render()}});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){const q=e.target.value.toLocaleLowerCase('fr');document.querySelectorAll('#catalog-results article').forEach(card=>card.hidden=!card.textContent.toLocaleLowerCase('fr').includes(q))}});
